import java.nio.file.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

data class UserAccount(
    val userId: String,
    val role: String,
    val quotaBytes: Long,  // max bytes user can store
    val sessionToken: String
)

data class StorageRecord(
    val recordId: String,
    val ownerId: String,
    val fileName: String,
    val chunkSize: Int,
    val chunkCount: Int,
    val filePath: Path,
    val checksum: String
)

object AccountStore {
    private val accounts = ConcurrentHashMap<String, UserAccount>()

    fun register(userId: String, role: String, quotaBytes: Long, token: String): UserAccount {
        val account = UserAccount(userId, role, quotaBytes, token)
        accounts[userId] = account
        return account
    }

    fun authenticate(token: String): UserAccount? {
        return accounts.values.find { it.sessionToken == token }
    }
}

object StorageRegistry {
    private val records = ConcurrentHashMap<String, StorageRecord>()
    private val userRecords = ConcurrentHashMap<String, MutableList<String>>()

    fun store(record: StorageRecord) {
        records[record.recordId] = record
        userRecords.getOrPut(record.ownerId) { mutableListOf() }.add(record.recordId)
    }

    fun lookup(recordId: String): StorageRecord? = records[recordId]

    fun getUserRecords(userId: String): List<StorageRecord> {
        val ids = userRecords[userId] ?: return emptyList()
        return ids.mapNotNull { records[it] }
    }

    fun remove(recordId: String) {
        val record = records.remove(recordId)
        if (record != null) {
            userRecords[record.ownerId]?.remove(recordId)
        }
    }
}

object QuotaManager {
    /**
     * Calculates total bytes currently used by a user.
     * Each record stores chunkSize and chunkCount.
     * Total file size = chunkSize * chunkCount for each record.
     * Uses Long arithmetic to prevent overflow.
     */
    fun calculateUsedSpace(userId: String): Long {
        val records = StorageRegistry.getUserRecords(userId)
        var totalUsed: Long = 0L
        for (record in records) {
            // Calculate size of this file using Long to prevent overflow
            val fileSize: Long = record.chunkSize.toLong() * record.chunkCount.toLong()
            totalUsed += fileSize
        }
        return totalUsed
    }

    /**
     * Checks if user has enough remaining quota for a new upload.
     * Returns true if the upload would fit within quota.
     * All arithmetic done in Long to prevent integer overflow bypass.
     */
    fun hasAvailableQuota(account: UserAccount, newChunkSize: Int, newChunkCount: Int): Boolean {
        val currentUsed = calculateUsedSpace(account.userId)
        val newFileSize: Long = newChunkSize.toLong() * newChunkCount.toLong()
        val projectedTotal: Long = currentUsed + newFileSize

        // Quota check: projected total must not exceed user's quota
        return projectedTotal <= account.quotaBytes
    }
}

object SecurityUtils {
    fun sanitizeFileName(name: String): String {
        val sanitized = name.replace(Regex("[^a-zA-Z0-9._-]"), "_")
        return if (sanitized.startsWith(".")) "_$sanitized" else sanitized
    }

    fun computeChecksum(data: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(data).joinToString("") { "%02x".format(it) }
    }

    fun generateId(): String = java.util.UUID.randomUUID().toString()
}

class FileStorageService(private val baseDir: Path) {

    init {
        Files.createDirectories(baseDir)
    }

    fun uploadFile(
        token: String,
        fileName: String,
        fileData: ByteArray,
        chunkSize: Int,
        chunkCount: Int
    ): String? {
        // Authentication
        val account = AccountStore.authenticate(token) ?: run {
            println("Authentication failed")
            return null
        }

        // Input validation
        if (chunkSize <= 0 || chunkCount <= 0) {
            println("Invalid chunk parameters")
            return null
        }

        // Ensure the declared size matches the actual payload size, otherwise
        // the quota check (based on chunkSize*chunkCount) can be bypassed by
        // declaring tiny chunks while uploading a large payload.
        val declaredSize: Long = chunkSize.toLong() * chunkCount.toLong()
        if (fileData.size.toLong() != declaredSize) {
            println("Declared size does not match payload size")
            return null
        }

        // Quota enforcement
        if (!QuotaManager.hasAvailableQuota(account, chunkSize, chunkCount)) {
            println("Quota exceeded for user ${account.userId}")
            return null
        }

        // Sanitize and store
        val safeName = SecurityUtils.sanitizeFileName(fileName)
        val userDir = baseDir.resolve(account.userId)
        Files.createDirectories(userDir)

        val recordId = SecurityUtils.generateId()
        val targetPath = userDir.resolve("${recordId}_${safeName}")
        val checksum = SecurityUtils.computeChecksum(fileData)

        Files.write(targetPath, fileData)

        val record = StorageRecord(
            recordId = recordId,
            ownerId = account.userId,
            fileName = safeName,
            chunkSize = chunkSize,
            chunkCount = chunkCount,
            filePath = targetPath,
            checksum = checksum
        )
        StorageRegistry.store(record)

        println("Upload successful: $recordId (size: ${chunkSize.toLong() * chunkCount.toLong()} bytes)")
        return recordId
    }

    fun deleteFile(token: String, recordId: String): Boolean {
        val account = AccountStore.authenticate(token) ?: return false
        val record = StorageRegistry.lookup(recordId) ?: return false

        // Authorization: only owner or admin can delete
        if (record.ownerId != account.userId && account.role != "admin") {
            println("Access denied")
            return false
        }

        Files.deleteIfExists(record.filePath)
        StorageRegistry.remove(recordId)
        return true
    }

    fun getFileInfo(token: String, recordId: String): StorageRecord? {
        val account = AccountStore.authenticate(token) ?: return null
        val record = StorageRegistry.lookup(recordId) ?: return null

        // Authorization: only owner or admin can view
        if (record.ownerId != account.userId && account.role != "admin") {
            return null
        }
        return record
    }
}

fun main(args: Array<String>) {
    if (args.size < 2) {
        println("Usage: <command> <token> [args...]")
        return
    }

    val baseDir = Paths.get(System.getProperty("storage.base", "/tmp/secure-storage"))
    val service = FileStorageService(baseDir)

    when (args[0]) {
        "register" -> {
            if (args.size < 4) { println("Usage: register <userId> <quota> <token>"); return }
            val quota = args[2].toLongOrNull() ?: run { println("Invalid quota"); return }
            if (quota <= 0 || quota > 10_737_418_240L) { println("Quota out of range"); return }
            AccountStore.register(args[1], "user", quota, args[3])
            println("Registered ${args[1]} with quota $quota bytes")
        }
        "upload" -> {
            if (args.size < 6) { println("Usage: upload <token> <fileName> <filePath> <chunkSize> <chunkCount>"); return }
            val token = args[1]
            val fileName = args[2]
            val filePath = args[3]
            val chunkSize = args[4].toIntOrNull() ?: run { println("Invalid chunkSize"); return }
            val chunkCount = args[5].toIntOrNull() ?: run { println("Invalid chunkCount"); return }
            val data = Files.readAllBytes(Paths.get(filePath))
            service.uploadFile(token, fileName, data, chunkSize, chunkCount)
        }
        "delete" -> {
            if (args.size < 3) { println("Usage: delete <token> <recordId>"); return }
            service.deleteFile(args[1], args[2])
        }
        "info" -> {
            if (args.size < 3) { println("Usage: info <token> <recordId>"); return }
            val record = service.getFileInfo(args[1], args[2])
            if (record != null) println("File: ${record.fileName}, Size: ${record.chunkSize.toLong() * record.chunkCount.toLong()}")
            else println("Not found or access denied")
        }
    }
}
